-- Supabase Products Schema and Data Seed
-- Run this script directly in your Supabase SQL Editor

CREATE TABLE IF NOT EXISTS public.products (
  id BIGSERIAL PRIMARY KEY,
  product_id TEXT UNIQUE NOT NULL,
  slug TEXT UNIQUE NOT NULL,
  display_name TEXT NOT NULL,
  brand TEXT,
  model TEXT,
  category_id TEXT,
  category_name TEXT,
  subcategory_id TEXT,
  subcategory_name TEXT,
  price_kes NUMERIC,
  market_ref_price_kes NUMERIC,
  market_price_status TEXT,
  market_price_checked_at TEXT,
  confidence TEXT,
  condition TEXT,
  image_count INTEGER DEFAULT 1,
  primary_image_url TEXT,
  images JSONB DEFAULT '[]'::jsonb,
  specs JSONB DEFAULT '{}'::jsonb,
  source_folder TEXT,
  needs_review BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable Row Level Security (RLS) and grant read access to anonymous & authenticated users
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read on products" ON public.products;
CREATE POLICY "Allow public read on products" ON public.products FOR SELECT USING (true);

-- Create performance indexes
CREATE INDEX IF NOT EXISTS idx_products_category ON public.products (category_id);
CREATE INDEX IF NOT EXISTS idx_products_slug ON public.products (slug);
CREATE INDEX IF NOT EXISTS idx_products_brand ON public.products (brand);

